constraints:
1 ≤ N ≤ 10^{5}

expected time complexity: O(N)
expected auxiliary space: O(N)

standard_solution_code:
class Solution:

	def countStrings(self, n):
		mod = 10 ** 9 + 7
		l = [0 for i in range(n + 1)]
		l[0] = 1
		l[1] = 2
		for i in range(2, n + 1):
			l[i] = l[i - 1] + l[i - 2]
		return l[-1] % mod
